'use strict';
const { Readable, Writable, finished } = require('readable-stream');

exports.count = function (words, done) {
  let total = 0;
  const sink = new Writable({
    write(chunk, encoding, callback) {
      total += String(chunk).length;
      callback();
    }
  });
  finished(sink, (err) => done(err ? -1 : total));
  Readable.from(words).pipe(sink);
};
